function styleText() { const st = STYLES[ST.style]; return st && st.text ? '\n\n' + st.text : ''; }
function styleBonus(b) { if (!ST.style || ST.style === 'mix') return 0; if (ST.style === 'sv') return b.style ? -0.5 : 0.5; return b.style === ST.style ? 5 : 0; }
const STYLE_HINT = { sv: 'Övningar från UEFA-, FA- och FIFA-material, sorterade efter SvFF:s skeden.', es: 'Rondos, positionsspel och situationsspel. Bollinnehav och positionering först.', de: 'Små spelformer, hög intensitet och direkt motpress efter bollförlust.', it: 'Kort och smalt lag, zonförsvar, positionsspel med jokrar och träning efter principer.', mix: 'Blandar övningar och idéer från alla skolor.' };
function bankFit(b, n, age) {
  const ageNum = parseInt(age) || (age === 'Senior' ? 20 : 12); const minAge = parseInt(b.ages) || 6;
  let score = 0; if (n >= b.min && n <= b.max) score += 3; else score -= Math.min(4, Math.abs(n < b.min ? b.min - n : n - b.max) / 2);
  if (ageNum + 2 >= minAge) score += 1; else score -= 3;
  return score;
}

