function replaceItem(id, item) { const i = ST.results.findIndex(r => r.id === id); if (i >= 0) ST.results.splice(i, 1, item); else ST.results.push(item); persist(); renderResults(); }
function removeItem(id) { const i = ST.results.findIndex(r => r.id === id); if (i >= 0) ST.results.splice(i, 1); renderResults(); }

/* ---------- Rendering ---------- */
