function bankToEx(b) { return { id: 'bank-' + b.id, name: b.name, phase: b.phase, stage: b.stage, type: b.type, minutes: 15, area: '', division: b.orig, organisation: b.org, setup: '', equipment: '', rules: b.rules, coachingPoints: b.points.slice(), questions: [], criteria: [], easier: b.easier || '', harder: b.harder || '', sketch: [], anim: ANIMS[b.id] || (ST.bankAnims || {})[b.id], basedOn: b.id, players: null, created: 0, fromBank: true }; }
