BANK.push(
  // ---- Lekar ----
  _LK({ id: 'w01', name: 'Trafikljus', min: 4, max: 24, orig: 'Ruta med koner, alla spelare har en boll, tränaren visar färger', org: 'Alla dribblar fritt i rutan. Tränaren håller upp en grön, gul eller röd kon (eller ropar färgen).', rules: 'Grönt: dribbla i full fart. Gult: sakta, små touch. Rött: stoppa bollen med sulan och frys. Den som är sist att stanna gör en snabb uppgift, till exempel tio tåtoucher.', points: ['Bollen nära foten när det går fort', 'Lyft blicken för att se färgen', 'Stoppa med sulan, inte med handen'], harder: 'Lägg till färger: blått = byt fot, vitt = vänd' }),
  _LK({ id: 'w02', name: 'Pirater', min: 6, max: 24, orig: 'Ruta med koner, alla har boll utom två pirater', org: 'Dribblarna har varsin boll. Två pirater utan boll står inne i rutan.', rules: 'Piraterna försöker sparka ut bollarna ur rutan. Den som blir av med bollen blir ny pirat, och piraten får bollen. Vem har aldrig varit pirat efter två minuter?', points: ['Skydda bollen med kroppen', 'Dribbla bort från piraten', 'Titta upp så att du ser var piraterna är'], src: 'fa_dare' }),
  _LK({ id: 'w03', name: 'Tunnelsvansen', min: 6, max: 20, orig: 'Smal kanal, dubbelt så lång som bred, med en stöldzon i mitten', src: 'fa_tunnel', org: 'Alla dribblare har en väst nedstoppad som svans. En försvarare står i stöldzonen.', rules: 'Dribbla genom kanalen och tillbaka på utsidan. Försvararen tar svansar, inte bollen. Alla börjar med fem liv och tappar ett per stulen svans, men får ett tillbaka när de tar sig igenom. Byt försvarare efter 60–90 sekunder.', points: ['Byt tempo när du närmar dig försvararen', 'Välj när du går nära och när du accelererar förbi', 'Huvudet upp för att hitta en väg'], harder: 'Två försvarare i stöldzonen' }),
  _LK({ id: 'w04', name: 'Kungen av ringen', min: 6, max: 20, orig: 'Ruta eller cirkel, alla har en boll', org: 'Alla dribblar inne i ytan med varsin boll.', rules: 'Skydda din egen boll och försök peta ut andras ur ytan. Den som blir av med bollen gör en snabb uppgift utanför och kommer sedan tillbaka. Vem åker ut minst gånger på två minuter?', points: ['Kroppen mellan motståndaren och bollen', 'Små touch och snabba riktningsbyten', 'Våga attackera andras bollar'], ages: '7+' }),
  _LK({ id: 'w05', name: 'Brokull med boll', min: 8, max: 20, orig: 'Ruta, en eller två kullare, en boll per par', org: 'En kullare jagar. Spelarna springer fritt, och några av dem dribblar med boll.', rules: 'Den som blir kullad står bredbent. Man blir fri när en lagkamrat passar bollen mellan benen. Byt kullare varje minut.', points: ['Passa med insidan och rätt tyngd', 'Hjälp varandra snabbt', 'Titta var kullaren är innan du passar'] }),
  _LK({ id: 'w06', name: 'Fånga konen', min: 8, max: 16, orig: 'Plan med en zon i varje ände och två koner i varje zon', org: 'Två lag. Varje lag ska ta motståndarnas koner.', rules: 'Ett lag får poäng när en spelare driver in i motståndarnas zon och tar en kon. Laget kan passa och dribbla fritt. Ny start från mitten efter varje poäng.', points: ['Driv in i fri yta', 'Passa när du blir stoppad', 'Försvara som ett lag och hjälp varandra'], type: 'Lek och reaktion', ages: '7+' }),
  // ---- Passning ----
  _PS({ id: 'w07', name: 'Passningsfyrkant med väggspel', min: 6, max: 16, orig: 'Kvadrat 15 × 15 m med en spelare vid varje hörn och kö vid start', org: 'Spelarna står vid hörnen A, B, C och D, med kö och bollar vid A.', rules: 'A spelar på B som kommer emot och lägger tillbaka. A slår djupt till C, som spelar till D, som avslutar varvet tillbaka till A-kön. Alla följer sin passning till nästa hörn.', points: ['Kom mot bollen innan mottagning', 'Väggpassningen på ett touch', 'Passa framför löpningen'], harder: 'Två bollar samtidigt' }),
  _PS({ id: 'w08', name: 'Passa och följ i triangel', min: 4, max: 12, orig: 'Triangel med koner, 10–12 m mellan, en extra spelare vid start', org: 'En spelare vid varje kon och en extra i kö.', rules: 'Passa och spring efter din passning till nästa kon. Byt håll varannan minut.', points: ['Öppna kroppen mot nästa mottagare', 'Ta emot med den fot som är längst bort', 'Hård, låg passning'], ages: '7+' }),
  _PS({ id: 'w09', name: 'Tredje man i romb', min: 5, max: 12, orig: 'Romb med fyra koner, A, B, C och D', org: 'En spelare vid varje kon, kö vid A.', rules: 'A spelar till B som kommer emot. B lägger av direkt till C (tredje man), som slår djupt till D. D vänder och driver tillbaka. Alla roterar en kon.', points: ['Tredje mannen ska vara spelbar innan bollen går till B', 'Läggningen på ett touch', 'Djupledspassningen framför D'], ages: '10+', level: 'B' }),
  _PS({ id: 'w10', name: 'Långa passningar över mittzonen', min: 5, max: 12, orig: 'Två par mittemot varandra ca 30 m isär, mittzon med en störande spelare', org: 'Spelarna står parvis i varsin ände. En spelare i mittzonen får störa.', rules: 'Slå långa passningar i luften över mittzonen. Mottagaren tar ner bollen med ett touch. Störaren byter rad efter tre passningar.', points: ['Lås fotleden och träffa under bollens mitt', 'Ta ner bollen mjukt med första touchen', 'Kroppen över bollen för en lägre passning'], ages: '11+' }),
  _PS({ id: 'w11', name: 'Passning genom portar', min: 4, max: 24, orig: 'Små konportar utspridda i en stor ruta, spelarna i par', org: 'Paren rör sig fritt mellan portarna med en boll.', rules: 'Passa genom en port till partnern och spring till en ny port. Hur många portar hinner paret på en minut?', points: ['Rörelse efter passningen', 'Titta upp för att hitta en ledig port', 'Passa med rätt tyngd'], ages: '6+' }),
  _PS({ id: 'w12', name: 'Mittfältarens vändning', min: 6, max: 12, orig: 'Tre spelare på linje: A, B (vändspelare) och C, med en passiv försvarare bakom B', org: 'A och C står i varsin ände. B står i mitten med en passiv försvarare bakom sig.', rules: 'A spelar till B, som scannar, tar emot på bakre foten, vänder bort från försvararen och spelar till C. C spelar tillbaka och alla roterar.', points: ['Scanna innan bollen kommer', 'Öppen kropp och mottagning på bakre foten', 'Vänd bort från pressen'], ages: '11+', level: 'B' }),
  // ---- Rondos och possession ----
  _RO({ id: 'w13', name: '6 mot 2 + 1 flytande', min: 9, max: 18, ages: '11+', level: 'B', src: 'st_rondo', orig: 'Ruta ca 15 × 15 m, sex runt kanten, två försvarare och en flytande spelare inne', org: 'Den flytande i mitten spelar alltid med laget som har bollen.', rules: 'Passningar genom mitten till den flytande ger en poäng. Försvararna pressar i par. Den som tappar bollen går in.', points: ['Stödvinklar runt bollhållaren', 'Hitta den centrala passningen', 'Försvararna: pressa i par och stäng mitten'] }),
  _RO({ id: 'w14', name: '5 mot 2 – träffa mittkonen', min: 7, max: 21, ages: '9+', src: 'st_rondo', orig: 'Ruta ca 10 × 10 m med en kon i mitten', org: 'Fem spelare runt rutan, två försvarare inne som skyddar konen.', rules: 'Sex passningar i rad ger en poäng. Träffar laget konen med en passning ger det två poäng.', points: ['Rör bollen tills en lucka uppstår', 'Passa hårt genom luckan', 'Försvararna: jobba ihop och skydda konen'], harder: 'En andra kon att skydda, eller två touch' }),
  _RO({ id: 'w15', name: 'Rondo i två zoner med vertikal poäng', min: 18, max: 18, ages: '12+', level: 'B', src: 'fifa_2zone', type: 'Positionsspel', orig: 'Zon A 10 × 30 m (2 mot 2 + 4) och zon B 15 × 30 m (3 mot 3 + 4), två dockor i mitten av varje zon', org: 'I varje zon finns en neutral i varje ände, en mellan dockorna och en fri. De neutrala spelar med laget som har bollen.', rules: 'Laget med boll ska föra bollen till andra änden. Poäng när bollen spelas genom mittspelaren mellan dockorna. Laget som vinner bollen måste spela till den neutrala i motsatt ände för att ta över.', points: ['Rör dig bakom motståndarnas presslinje', 'Ta emot på bakre foten med öppen kropp', 'Välj rätt läge att spela framåt'], harder: 'Mittspelaren har ett touch' }),
  _RO({ id: 'w16', name: 'Trefärgsrondo 4 + 4 mot 4', min: 12, max: 12, ages: '11+', level: 'B', src: 'icoach', orig: 'Ruta ca 25 × 25 m, tre lag om fyra', org: 'Två lag håller bollen tillsammans mot det tredje.', rules: 'När det jagande laget vinner bollen ropar de en färg, och det laget spelar med dem. Laget som inte ropas jagar. Motpressa tills en färg har ropats.', points: ['Kommunicera högt vid bollvinst', 'Ställ om direkt när din färg inte ropas', 'Gör ytan stor när ni har bollen'] }),
  _RO({ id: 'w17', name: 'Slutzonsspel', min: 8, max: 16, ages: '9+', src: 'veo', type: 'Positionsspel', orig: 'Plan ca 30 × 20 m med en 3 m bred slutzon i varje ände', org: 'Två lag spelar mot varandra. Försvarare får inte gå in i slutzonerna.', rules: 'Poäng när laget passar till en lagkamrat som tar emot kontrollerat i motståndarnas slutzon. Ny start från mitten efter poäng.', points: ['Tajma löpningen in i zonen', 'Spela till fördel innan djupledspassningen', 'Laget utan boll: stäng passningsvägarna framåt'] }),
  _RO({ id: 'w18', name: '6 mot 3 genom konportar', min: 9, max: 9, ages: '10+', src: 'icoach', orig: 'Ruta ca 30 × 30 m med fyra konportar på 2 m', org: 'Sex anfallare mot tre försvarare.', rules: 'Anfallarna får poäng när de passar eller dribblar genom en konport. Vinner försvararna bollen byter lagen roller. Flest portar efter tre minuter vinner.', points: ['Locka försvararna till en port och spela till en annan', 'Driv in i ytan när du är fri', 'Försvararna: stäng den närmaste porten'] }),
  _RO({ id: 'w19', name: 'Jaktrondo 6 mot 2 med byten', min: 10, max: 14, ages: '10+', src: 'icoach', orig: 'Ruta ca 12 × 12 m och en startkon 10 m utanför', org: 'Sex håller bollen. Jagarna står parvis vid startkonen.', rules: 'Tränaren spelar in och ett par springer in och jagar i tio sekunder, sedan kommer nästa par. Paret som vinner flest bollar vinner.', points: ['Full intensitet i tio sekunder', 'Pressa i par: en på bollen, en stänger', 'Bollhållarna: få touch och rörelse'] }),
  _RO({ id: 'w20', name: '3 mot 1 i ruta', min: 4, max: 16, ages: '7+', orig: 'Ruta ca 7 × 7 m, tre runt kanten och en inne', src: 'icoach', org: 'Tre spelare håller bollen mot en i mitten. Flera rutor bredvid varandra.', rules: 'Passa förbi mittspelaren. Spelaren utan boll flyttar sig så att den alltid är spelbar. Den som tappar bollen går in.', points: ['Rör dig till det hörn som ger en passningsväg', 'Passa på den fot som är längst bort', 'Mittspelaren: stäng en passningsväg i taget'], harder: 'Två touch eller bara svaga foten' }),
  // ---- Dueller ----
  _DU({ id: 'w21', name: '1 mot 1 och avslut', min: 2, max: 20, ages: '7+', src: 'fa_1v1', orig: 'Konmål eller småmål, grupper om två eller tre', org: 'Försvararen står vid målet med bollen, anfallaren en bit ut.', rules: 'Försvararen passar till anfallaren och kliver ut. Anfallaren försöker göra mål. Byt roller efter varje försök. Lägg till en målvakt för att göra det svårare.', points: ['Första touchen framåt', 'Finta och gå åt andra hållet', 'Välj avslut efter var målet är öppet'], easier: 'Större mål', harder: 'Tidsgräns eller touchgräns för anfallaren' }),
  _DU({ id: 'w22', name: 'Reaktionsduell 1 mot 1', min: 4, max: 16, ages: '8+', src: 'icoach', orig: 'Två mål mittemot varandra, två spelare sida vid sida i mitten, tränaren med bollar vid sidan', org: 'Varje spelare anfaller ett eget mål.', rules: 'Tränaren spelar in bollen. Den som är först på bollen anfaller sitt mål, den andra försvarar. Byt spelare efter varje duell.', points: ['Reagera på passningen, inte på signalen', 'Skydda bollen när du vänder', 'Försvararen: snabbt goal side'] }),
  _DU({ id: 'w23', name: '2 mot 1 blir 2 mot 2', min: 6, max: 14, ages: '9+', src: 'icoach', orig: 'Mål med målvakt, två anfallare mot en försvarare, en andra försvarare som startar vid sidan', org: 'Anfallarna startar 2 mot 1. Den andra försvararen startar tre sekunder senare.', rules: 'Anfallarna försöker göra mål innan den andra försvararen hinner hem. Vinner försvararna bollen passar de till tränaren för en poäng.', points: ['Driv mot försvararen för att binda honom', 'Passa när försvararen kliver', 'Avsluta snabbt innan överläget försvinner'] }),
  _DU({ id: 'w24', name: 'Duell med ryggen mot mål', min: 4, max: 12, ages: '10+', orig: 'Mål med målvakt, en anfallare med ryggen mot mål och en försvarare bakom, en passare 20 m ut', src: 'icoach', org: 'Passaren spelar in till anfallaren, som har försvararen i ryggen.', rules: 'Anfallaren ska vända och avsluta. Försvararen som vinner bollen spelar tillbaka till passaren för en poäng. Byt roller efter tre försök.', points: ['Känn försvararen med kroppen innan bollen kommer', 'Vänd åt det håll försvararen inte står', 'Avsluta snabbt efter vändningen'] }),
  _DU({ id: 'w25', name: '1 mot 1 mot fyra portar', min: 2, max: 16, ages: '7+', orig: 'Ruta med en konport mitt på varje sida', src: 'fa_dare', org: 'En anfallare med boll mot en försvarare.', rules: 'Anfallaren får poäng genom att driva genom valfri port. Försvararen som vinner bollen anfaller direkt. Spela i 45 sekunder och byt.', points: ['Finta åt ett håll och gå mot en annan port', 'Byt tempo', 'Försvararen: stäng den närmaste porten'] }),
  _DU({ id: 'w26', name: 'Sprintduell runt käppen', min: 4, max: 14, ages: '9+', src: 'icoach', orig: 'Mål med målvakt, två käppar 30 m ut, tränaren med bollar', org: 'Två spelare står vid varsin käpp med ryggen mot mål.', rules: 'Tränaren spelar ut en boll mot mål. Båda sprintar runt sin käpp. Den som är först på bollen anfaller, den andra försvarar.', points: ['Explosiv start runt käppen', 'Skydda bollen när du kommer först', 'Avsluta innan försvararen kommer ikapp'] }),
);
