/* ---------- Visa för spelarna (helskärm) ---------- */
let wakeLock = null;
let BOARD_ID = null;
function openBoard(ex) {
  BOARD_ID = ex.id;
  const root = $('#board-root'); const sid = 'bd-' + ex.id; const hasMoves = (ex.sketch || []).some(e => ['pass', 'run', 'drib'].includes(e.t));
  root.innerHTML = '<div class="board" role="dialog" aria-label="Visa för spelarna"><div class="board-in">' +
    '<div class="spread"><span class="board-k">' + esc(ex.phase + (ex.stage ? ' · ' + ex.stage : '')) + '</span><button type="button" class="board-close" data-a="closeBoard">Stäng</button></div>' +
    '<h2 class="board-h">' + esc(ex.name) + '</h2>' + (ex.division ? '<div class="board-div num">' + esc(ex.division) + '</div>' : '') +
    animBlock(ex, 'bd-' + ex.id, { noStatus: true }) + kitRow(ex) +
    (ex.rules ? '<div><div class="board-k">Regler</div><p class="board-p">' + esc(ex.rules) + '</p></div>' : '') +
    ((ex.coachingPoints || []).length ? '<div><div class="board-k">Tänk på</div><ul class="board-ul">' + ex.coachingPoints.map(c => '<li>' + esc(c) + '</li>').join('') + '</ul></div>' : '') +
    '</div></div>';
  document.body.style.overflow = 'hidden';
  try { if (navigator.wakeLock) navigator.wakeLock.request('screen').then(l => wakeLock = l).catch(() => { }); } catch (e) { }
}
function closeBoard() { if (ACT && ACT.u.startsWith('bd-')) { animPause(); ACT = null; } BOARD_ID = null; $('#board-root').innerHTML = ''; document.body.style.overflow = ''; try { if (wakeLock) wakeLock.release(); } catch (e) { } wakeLock = null; }

/* ---------- Ändra antal spelare (dialog) ---------- */
let ADAPT = null;
function openAdapt(ex) {
  ADAPT = { id: ex.id, n: ST.n !== ex.players ? ST.n : ex.players, gk: ST.n !== ex.players ? ST.gk : (ex.gk ?? ST.gk) };
  renderAdapt();
}
function renderAdapt() {
  const ex = findEx(ADAPT.id); if (!ex) return closeAdapt();
  $('#modal-root').innerHTML = '<div class="modal-wrap" data-a="modalBg"><div class="modal" role="dialog" aria-modal="true" aria-label="Ändra antal spelare"><div class="spread"><h2>Ändra antal spelare</h2><button type="button" class="btn sm ghost" data-a="closeAdapt">Stäng</button></div><p class="muted">"' + esc(ex.name) + '" är gjord för ' + (ex.players || '?') + ' spelare. Hur många har du nu?</p>' +
    '<div class="spread"><b>Spelare</b><span class="stepper"><button type="button" data-a="adN" data-d="-1" aria-label="Färre">−</button><output class="num">' + ADAPT.n + '</output><button type="button" data-a="adN" data-d="1" aria-label="Fler">+</button></span></div>' +
    '<div class="spread"><b>Varav målvakter</b><span class="stepper"><button type="button" data-a="adG" data-d="-1" aria-label="Färre">−</button><output class="num">' + ADAPT.gk + '</output><button type="button" data-a="adG" data-d="1" aria-label="Fler">+</button></span></div>' +
    '<button type="button" class="btn primary big" data-a="doAdapt">' + IC_SPARK + 'Anpassa övningen</button></div></div>';
}
function closeAdapt() { ADAPT = null; $('#modal-root').innerHTML = ''; }

/* ---------- Händelser ---------- */
function readExtra() { const e = $('#extra'); if (e) ST.extra = e.value; }
function asText(ex) {
  const L = [ex.name + ' (' + ex.phase + (ex.stage ? ' – ' + ex.stage : '') + ', ' + ex.minutes + ' min)', [ex.division, ex.area].filter(Boolean).join(' · '), ''];
  if (ex.explanation) L.push('Förklaring: ' + ex.explanation);
  if ((ex.criteria || []).length) L.push('Spelkriterier: ' + ex.criteria.join(' | '));
  L.push('', 'Organisation: ' + ex.organisation);
  if (ex.setup) L.push('Uppställning: ' + ex.setup);
  if (ex.equipment) L.push('Material: ' + ex.equipment);
  L.push('Regler: ' + ex.rules);
  const bt = ex.basedOn && bankById(ex.basedOn); if (bt && SOURCES[bt.src]) L.push('Bygger på: ' + bt.name + ' (' + SOURCES[bt.src].org + ')');
  if (ex.work) L.push('Arbete och vila: ' + ex.work);
  if ((ex.coachingPoints || []).length) L.push('', 'Coachpunkter:', ...ex.coachingPoints.map(c => '• ' + c));
  if ((ex.questions || []).length) L.push('Fråga spelarna:', ...ex.questions.map(c => '• ' + c));
  if (ex.easier) L.push('', 'Lättare: ' + ex.easier); if (ex.harder) L.push('Svårare: ' + ex.harder);
  return L.join('\n');
}
const A = {
  n: el => { ST.n = Math.max(2, Math.min(40, ST.n + Number(el.dataset.d))); if (ST.gk > ST.n - 2) ST.gk = Math.max(0, ST.n - 2); persist(); render(); },
  setn: el => { ST.n = Number(el.dataset.v); if (ST.gk > ST.n - 2) ST.gk = Math.max(0, ST.n - 2); persist(); render(); },
  gk: el => { ST.gk = Math.max(0, Math.min(Math.min(4, ST.n - 2), ST.gk + Number(el.dataset.d))); persist(); render(); },
  phase: el => { ST.phase = el.dataset.k; ST.stage = ''; ST.rot = 0; persist(); render(); },
  stage: el => { ST.stage = el.dataset.v; ST.rot = 0; persist(); render(); },
  mode: el => { readExtra(); ST.mode = el.dataset.v; persist(); render(); },
  set: el => { readExtra(); ST[el.dataset.k] = el.dataset.k === 'minutes' ? Number(el.dataset.v) : el.dataset.v; ST.moreOpen = true; persist(); render(); },
  view: el => { ST.view = el.dataset.v; persist(); render(); window.scrollTo(0, 0); },
  edit: () => { ST.editOpen = true; render(); window.scrollTo(0, 0); },
  closeEdit: () => { readExtra(); ST.editOpen = false; persist(); render(); },
  savedFilter: el => { ST.savedFilter = el.dataset.k; persist(); render(); },
  bankFilter: el => { ST.bankFilter = el.dataset.k; persist(); render(); },
  bankStyle: el => { ST.bankStyle = el.dataset.k; persist(); render(); },
  style: el => { readExtra(); ST.style = el.dataset.k; persist(); render(); },
  fromBank: el => { const b = bankById(el.dataset.id); if (!b || isBusy()) return; markUsed(b.id); ST.view = 'make'; ST.editOpen = false; persist(); generate(1, null, [{ phase: b.phase, stage: b.stage, type: b.type, tpl: b.id }]); setTimeout(() => window.scrollTo(0, document.body.scrollHeight), 80); toast('Anpassar ' + b.name + ' till ' + ST.n + ' spelare'); },
  go: () => { readExtra(); persist(); if (ST.mode === 'prog') generateProg(); else generate(3); window.scrollTo(0, 0); },
  more: () => { if (ST.mode === 'prog') generateProg(); else generate(3); },
  like: el => { const ex = findEx(el.dataset.id); if (ex) { generate(2, ex); toast('Skapar två varianter av ' + ex.name); } },
  retry: el => { const i = ST.results.findIndex(r => r.id === el.dataset.id); if (i < 0) return; const spec = ST.results[i].spec; ST.results.splice(i, 1); if (!batchCtl || batchCtl.signal.aborted) batchCtl = new AbortController(); const job = { id: 'job-' + uid(), pending: true, spec }; ST.results.splice(i, 0, job); renderResults(); useCap('sample').then(s => { if (s) runJob(job, s).then(() => { persist(); render(); }); else replaceItem(job.id, { id: job.id, failed: true, spec, err: 'AI är inte tillgängligt här.' }); }); },
  dismiss: el => removeItem(el.dataset.id),
  stop: () => { if (batchCtl) batchCtl.abort(); },
  clear: () => { if (isBusy()) return; if (A.clear.armed) { ST.results = []; errMsg = ''; ST.editOpen = true; OPEN.clear(); persist(); render(); A.clear.armed = false; toast('Listan är rensad. Sparade övningar finns kvar.'); } else { A.clear.armed = true; toast('Tryck på Rensa igen för att tömma listan'); setTimeout(() => A.clear.armed = false, 3000); } },
  toggle: el => { const id = el.dataset.id; if (OPEN.has(id)) OPEN.delete(id); else OPEN.add(id); if (ST.view === 'saved') render(); else renderResults(); },
  fav: el => { const ex = findEx(el.dataset.id); if (!ex) return; if (SAVED[ex.id] && !SAVED[ex.id].removed) { unsaveFav(ex.id); toast('Borttagen från favoriter'); } else { saveFav(ex); toast('Tillagd i favoriter'); } if (ST.view !== 'make' || ST.editOpen) render(); else renderResults(); const tb = document.querySelector('[data-a="view"][data-v="saved"]'); if (tb) tb.textContent = 'Favoriter (' + savedList().length + ')'; },
  copy: async el => { const ex = findEx(el.dataset.id); if (!ex) return; try { await navigator.clipboard.writeText(asText(ex)); toast('Övningen är kopierad'); } catch (e) { toast('Kunde inte kopiera på den här enheten'); } },
  anim: el => animateSvg(el.dataset.svg, findEx(el.dataset.id), el),
  show: el => { const ex = findEx(el.dataset.id); if (ex) openBoard(ex); },
  closeBoard: () => closeBoard(),
  aplay: el => { const u = el.dataset.u; if (ACT && ACT.u === u && ACT.playing) animPause(); else animStart(u, el.dataset.id); },
  astep: el => { const u = el.dataset.u; if (!ACT || ACT.u !== u) { animStart(u, el.dataset.id, 0); } animPause(); const n = ACT.F.length; ACT.t = Math.max(0, Math.min(n - 1, (Number(el.dataset.d) > 0 ? Math.floor(ACT.t + 1e-6) + 1 : Math.ceil(ACT.t - 1e-6) - 1))); animDraw(); setBtn(); },
  aspeed: el => { const u = el.dataset.u; if (!ACT || ACT.u !== u) { animStart(u, el.dataset.id, 0); animPause(); } ACT.speed = ACT.speed === 1 ? .5 : ACT.speed === .5 ? 2 : 1; setBtn(); },
  mkAnim: el => { const ex = findEx(el.dataset.id); if (ex) requestAnim(ex); },
  bankAnim: el => { const b = bankById(el.dataset.id); if (b && !ST.bankAnimBusy) requestBankAnim(b); },
  adaptOpen: el => { const ex = findEx(el.dataset.id); if (ex) openAdapt(ex); },
  closeAdapt: () => closeAdapt(),
  modalBg: (el, e) => { if (e.target === el) closeAdapt(); },
  adN: el => { ADAPT.n = Math.max(2, Math.min(40, ADAPT.n + Number(el.dataset.d))); if (ADAPT.gk > ADAPT.n - 2) ADAPT.gk = Math.max(0, ADAPT.n - 2); renderAdapt(); },
  adG: el => { ADAPT.gk = Math.max(0, Math.min(Math.min(4, ADAPT.n - 2), ADAPT.gk + Number(el.dataset.d))); renderAdapt(); },
  doAdapt: () => { const a = ADAPT; closeAdapt(); adaptExercise(a.id, a.n, a.gk); },
};
document.addEventListener('click', e => { const el = e.target.closest('[data-a]'); if (!el) return; const fn = A[el.dataset.a]; if (fn) fn(el, e); });
document.addEventListener('toggle', e => { if (e.target.matches && e.target.matches('details.more')) ST.moreOpen = e.target.open; }, true);
document.addEventListener('input', e => { if (e.target.id === 'extra') { ST.extra = e.target.value; persist(); } });
document.addEventListener('keydown', e => { if (e.key === 'Escape') { if (DR) return; if ($('#board-root').innerHTML) closeBoard(); else if (ADAPT) closeAdapt(); } });

/* ---------- Kategorier ---------- */
const CATS = [
  ['lek', 'Lekar och reaktion', 'Lekfulla övningar med sprint, reaktion och mycket skratt. Passar som uppvärmning och för de yngsta.'],
  ['pass', 'Passningar', 'Passningsmönster med koner och käppar: tillslag, mottagning, väggspel och löpningar.'],
  ['poss', 'Possession och rondos', 'Hålla bollen mot jagare: rondos, positionsspel och bollinnehav.'],
  ['duel', 'Dueller och dribbling', '1 mot 1, 2 mot 2 och att ta sig förbi en motståndare med bollen.'],
  ['fin', 'Avslut', 'Komma till lägen och göra mål: avslutsövningar och anfall i överlägsenhet.'],
  ['spel', 'Spelövningar och smålagsspel', 'Spel med riktning, smålagsspel och matchlikt spel.'],
  ['press', 'Press och omställning', 'Vinna tillbaka bollen, pressa uppbyggnad och agera direkt vid bollförlust.'],
  ['def', 'Försvara mål', 'Försvara straffområdet: inlägg, djup i backlinjen och 1 mot 1 mot mål.'],
];
const CAT_OVR = { t06: 'spel', s03: 'poss' };
function catOf(b) {
  if (b.cat) return b.cat;
  if (CAT_OVR[b.id]) return CAT_OVR[b.id];
  const t = b.type || '', s = b.stage || '';
  if (/^Lek|Teknik och samarbete/.test(t)) return 'lek';
  if (/Passningsövning/.test(t)) return 'pass';
  if (s === 'Förhindra och rädda avslut') return 'def';
  if (/^Duell/.test(t)) return 'duel';
  if (['Återerövring', 'Förhindra speluppbyggnad', 'Omställning till försvar'].includes(s)) return 'press';
  if (/Rondo|Positionsspel/.test(t)) return 'poss';
  if (/Avslutsövning/.test(t) || s === 'Komma till avslut och göra mål') return 'fin';
  return 'spel';
}
const catName = k => (CATS.find(c => c[0] === k) || [, ''])[1];
var bankBrowseHTML; /* äldre version borttagen, den aktuella definieras längre ner */
Object.assign(A, {
  bankGroup: el => { ST.bankGroup = el.dataset.k; persist(); render(); },
  bankCat: el => { ST.bankCat = el.dataset.k; persist(); render(); },
});

/* ============ v8: markera spelare, material, sök, rita egna, importera från foto ============ */
document.body.insertAdjacentHTML('beforeend', '<div id="draw-root"></div>');

