  const parts = [c.a && c.a + ' orange', c.b && c.b + ' blå', c.joker && c.joker + (c.joker > 1 ? ' jokrar' : ' joker'), c.gk && c.gk + (c.gk > 1 ? ' målvakter' : ' målvakt')].filter(Boolean);
