async function checkImages() { try { const s = await useCap('sample'); if (!s || !s.limits) { IMG_OK = false; return; } const l = await s.limits(); IMG_OK = !!(l && l.images); } catch (e) { IMG_OK = false; } if (ST.view === 'draw') render(); }
