    const an = cleanAnim(out && out.anim); if (!an) throw { code: 'invalid_json' };
    const x = (out && out.exercise) || {};
    const phase = ['Anfall', 'Försvar', 'Omställning'].includes(x.phase) ? x.phase : 'Anfall';
    const D = drFromAnim(an, { name: String(x.name || 'Övning från bild').slice(0, 80), phase, stage: PHASES[phaseKey(phase)].stages.includes(x.stage) ? x.stage : '', organisation: String(x.organisation || '').slice(0, 1200), rules: String(x.rules || '').slice(0, 800), points: (Array.isArray(x.coachingPoints) ? x.coachingPoints : []).slice(0, 4).map(s => String(s).slice(0, 160)).join('\n') });
    D.banner = 'AI:n har gjort om bilden till en animation. Kolla att spelarna står rätt, dra dem om något är fel, och tryck på Spara.';
    D.fromPhoto = true; D.preview = true; D.dirty = true;
