document.addEventListener('toggle', e => { if (e.target.matches && e.target.matches('details.pack')) ST.packOpen = e.target.open; if (DR && e.target.matches && e.target.matches('details.draw-det')) DR.details = e.target.open; }, true);
Object.assign(A, {
  hl: el => { const u = el.dataset.u, id = el.dataset.pid; HL[u] = HL[u] === id ? null : id; refreshPitch(u, el.dataset.id); },
  hlClear: el => { HL[el.dataset.u] = null; refreshPitch(el.dataset.u, el.dataset.id); },
  today: el => { const id = el.dataset.id; const t = new Set(ST.today || []); if (t.has(id)) t.delete(id); else t.add(id); ST.today = [...t]; ST.packOpen = true; persist(); render(); },
  aiSearch: () => aiSearch(),
  clearSearch: () => { ST.bankQ = ''; SEARCH = null; persist(); render(); },
  searchMake: () => {
    const q = (ST.bankQ || '').trim(); if (!q || isBusy()) return;
    ST.extra = q.slice(0, 300); ST.moreOpen = true;
    if (SEARCH && SEARCH.q === q && SEARCH.stage) { const ph = stagePhase(SEARCH.stage); ST.phase = phaseKey(ph); ST.stage = SEARCH.stage; }
    ST.view = 'make'; ST.editOpen = false; persist(); generate(3); window.scrollTo(0, 0); toast('Skapar tre övningar för ditt problem');
  },
  drNew: () => openDraw(drBlank()),
  drResume: () => { const d = ST.draft; if (!d) return; openDraw(Object.assign(drBlank(), clone(d), { hist: [] })); },
  drDiscard: () => { if (A.drDiscard.armed) { delete ST.draft; persist(); render(); A.drDiscard.armed = false; toast('Utkastet är slängt'); } else { A.drDiscard.armed = true; toast('Tryck på Släng igen för att slänga utkastet'); setTimeout(() => A.drDiscard.armed = false, 3000); } },
  drEdit: el => { const ex = findEx(el.dataset.id); if (!ex) return; openDraw(drFromEx(ex)); },
  drClose: () => { drReadInputs(); drSaveDraft(); closeDraw(); if (ST.view === 'draw') render(); toast('Utkastet finns kvar under Rita'); },
  drSave: () => saveDraw(),
  drTool: el => { drReadInputs(); DR.tool = el.dataset.k; DR.note = ''; document.querySelectorAll('.dtool').forEach(b => { const on = b.dataset.k === DR.tool; b.classList.toggle('on', on); b.setAttribute('aria-pressed', on); }); drRenderPitch(); },
  drStep: el => { drReadInputs(); DR.k = Number(el.dataset.i); DR.note = ''; drRender(); },
  drAddStep: () => { drReadInputs(); if (DR.frames.length >= 26) return; drSnap(); const f = DR.frames[DR.k]; DR.frames.splice(DR.k + 1, 0, { c: '', p: clone(f.p), b: Array.isArray(f.b) ? f.b.slice() : f.b }); DR.k++; if (DR.tool !== 'ball') DR.tool = 'move'; DR.note = ''; drRender(); drSaveDraft(); },
  drDelStep: () => { drReadInputs(); if (DR.k === 0) return; drSnap(); DR.frames.splice(DR.k, 1); DR.k = Math.max(0, DR.k - 1); drRender(); drSaveDraft(); },
  drUndo: () => { const D = DR; if (!D.hist.length) return; const o = JSON.parse(D.hist.pop()); D.labels = o.labels; D.s = o.s; D.frames = o.frames; D.k = Math.min(o.k, o.frames.length - 1); D.note = ''; drRender(); drSaveDraft(); },
  drPreview: () => { drReadInputs(); DR.preview = !DR.preview; if (ACT && ACT.u === 'dr') { animPause(); ACT = null; } drRender(); if (DR.preview) setTimeout(() => animStart('dr', '__draw', 0), 60); },
  drPhase: el => { drReadInputs(); DR.phase = el.dataset.v; DR.stage = ''; DR.details = true; drRender(); },
  drStage: el => { drReadInputs(); DR.stage = DR.stage === el.dataset.v ? '' : el.dataset.v; DR.details = true; drRender(); },
  drDescribe: () => drDescribe(),
  ownDel: el => { const id = el.dataset.id; if (A.ownDel.armed === id) { unsaveFav(id); A.ownDel.armed = null; render(); toast('Övningen är borttagen'); } else { A.ownDel.armed = id; toast('Tryck på Ta bort igen för att radera övningen'); setTimeout(() => { if (A.ownDel.armed === id) A.ownDel.armed = null; }, 3000); } },
});
