        h += '<section class="sec"><div class="sec-head"><span class="pill ' + PHASES[k].cls + '">' + esc(PHASES[k].label) + '</span><h2 class="grow">' + esc(stage) + ' <span class="cnt num">' + list.length + '</span></h2></div>' + tilesOf(list.map(b => bankCard(b))) + '</section>';
