function openDet(id, keepScroll) {
  const ex = findEx(id); if (!ex) return;
  const wasOpen = !!DET; DET = id;
  if (!keepScroll && ACT && ACT.u.startsWith('dt-')) { animPause(); ACT = null; }
  const root = $('#detail-root'); const sc = keepScroll && root.firstChild ? root.firstChild.scrollTop : 0;
  root.innerHTML = detHTML(ex); document.body.style.overflow = 'hidden';
  if (sc) root.firstChild.scrollTop = sc;
  if (keepScroll && ACT && ACT.u === 'dt-' + id) { ACT.els = {}; setTimeout(() => { animDraw(); setBtn(); }, 0); }
  if (!wasOpen) { try { history.pushState({ det: id }, ''); } catch (e) { } }
  if (!keepScroll && !['b14', 'b15', 'b21', 'b28', 'oa2', 'w06', 's03', 'w21', 'w22', 'w23', 'w24', 'w25', 'w26', 't71', 't70', 'w44', 'w45', 'w46', 'fu2', 'fu5', 'ae1', 'ff20', 'svb35731', 'svb34243', 'svb164617', 'svb122212', 'svb1992', 'b19', 'b08', 'b09', 'b10', 'b11', 'b12', 'b13', 'e04', 'g05', 'g07', 'i02', 'i07', 't06', 't07', 't13', 't18', 't30', 't31', 't32', 't33', 't34', 't35', 't36', 't37', 't38', 't39', 't40', 't41', 't42', 't43', 't45', 't46'].includes(ex.basedOn)) setTimeout(() => { if (DET === id) animStart('dt-' + id, id, 0); }, 450);
}
function closeDet(fromPop) {
  if (!DET) return; DET = null;
  if (ACT && ACT.u.startsWith('dt-')) { animPause(); ACT = null; }
  $('#detail-root').innerHTML = ''; if (!$('#board-root').innerHTML && !DR) document.body.style.overflow = '';
  if (!fromPop) { try { if (history.state && history.state.det) history.back(); } catch (e) { } }
}
window.addEventListener('popstate', () => { if (DET) closeDet(true); });

