/* ---------- Händelser ---------- */
document.addEventListener('change', e => { const k = e.target && e.target.dataset && e.target.dataset.change; if (k === 'bankStyle') { ST.bankStyle = e.target.value; persist(); render(); } });
document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && DET && !DR && !$('#board-root').innerHTML) { closeDet(); return; }
  if ((e.key === 'Enter' || e.key === ' ') && e.target.classList && e.target.classList.contains('tile')) { e.preventDefault(); openDet(e.target.dataset.id); }
});
const __fav = A.fav, __fromBank = A.fromBank, __drEdit = A.drEdit, __ownDel = A.ownDel, __show = A.show;
Object.assign(A, {
  open: el => openDet(el.dataset.id),
  closeDet: () => closeDet(),
  fav: el => { __fav(el); if (DET) openDet(DET, true); renderNav(); },
  fromBank: el => { if (DET) closeDet(); __fromBank(el); },
  drEdit: el => { if (DET) closeDet(); __drEdit(el); },
  ownDel: el => { const armed = A.ownDel.armed === el.dataset.id; __ownDel(el); if (armed && DET) closeDet(); },
  ajump: el => { const u = el.dataset.u; if (!ACT || ACT.u !== u) animStart(u, el.dataset.id, 0); animPause(); ACT.hold = 0; ACT.t = Number(el.dataset.k); animDraw(); setBtn(); },
  togArrows: el => { ST.arrows = ST.arrows === false; persist(); document.body.classList.toggle('no-arrows', ST.arrows === false); el.classList.toggle('on', ST.arrows !== false); el.setAttribute('aria-pressed', ST.arrows !== false); },
  togLoop: el => { ST.loop = !ST.loop; persist(); el.classList.toggle('on', ST.loop); el.setAttribute('aria-pressed', ST.loop); if (ACT && ST.loop && !ACT.playing && ACT.t >= ACT.F.length - 1.001) animStart(ACT.u, ACT.id, 0); },
});

