  h += '<div class="run-ctl" aria-label="Timerkontroller"><button type="button" class="run-b" data-a="runPrev"' + (RUN.i ? '' : ' disabled') + ' aria-label="Föregående block">‹</button><button type="button" class="run-b main" data-a="runToggle">' + (RUN.running ? '❚❚ Paus' : RUN.done ? '↺ Starta om' : '▶ Starta') + '</button><button type="button" class="run-b" data-a="runPlus" aria-label="En minut till">+1</button><button type="button" class="run-b" data-a="runNext"' + (nb ? '' : ' disabled') + ' aria-label="Nästa block">›</button></div>';
