    (ins.length ? '<ul class="cp">' + ins.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '') +
    (ai ? '<div class="ai-patt"><b>AI:n ser:</b><ul class="cp">' + ai.items.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul></div>' : done.length >= 2 ? '<button type="button" class="btn" data-a="aiPatterns"' + (PATBUSY ? ' disabled' : '') + '>' + (PATBUSY ? BALL.replace('ball-spin', 'ball-spin sm') + ' Analyserar …' : IC_SPARK + 'Låt AI:n hitta mönster') + '</button>' : '') + '</section>';
