const PITCH_P = '<rect x="0" y="0" width="68" height="105" fill="var(--pitch)"/>' + Array.from({ length: 7 }, (_, i) => i % 2 ? '<rect x="0" y="' + i * 15 + '" width="68" height="15" fill="var(--pitch-2)"/>' : '').join('') + '<g fill="none" stroke="var(--pitch-line)" stroke-width=".5"><rect x="1" y="1" width="66" height="103"/><line x1="1" y1="52.5" x2="67" y2="52.5"/><circle cx="34" cy="52.5" r="7"/><rect x="14" y="1" width="40" height="16"/><rect x="25" y="1" width="18" height="5.5"/><rect x="14" y="88" width="40" height="16"/><rect x="25" y="98.5" width="18" height="5.5"/><rect x="30" y="-1" width="8" height="2"/><rect x="30" y="104" width="8" height="2"/></g>';
