const IMG_W = 1080, IMG_PAD = 48;
const IMG_FONT = 'system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif';
function imgSafeName(s) { return ((s.name || 'pass').replace(/[^\wåäöÅÄÖ \-]+/g, '').trim().slice(0, 60) || 'pass') + ' ' + (s.date || ''); }
