  x.font = '600 28px ' + IMG_FONT; x.fillStyle = '#CFE8DA'; x.fillText(meta, IMG_PAD, y + 4); y += 44;
  x.font = '500 28px ' + IMG_FONT; x.fillStyle = '#ffffff'; focusL.forEach(l => { x.fillText(l, IMG_PAD, y); y += 36; });
