    x.fillText((r.i + 1) + '. ' + kindName(r.b.kind).toUpperCase() + ' · ' + r.b.min + ' MIN  (' + r.st + '–' + r.en + ')', TX, ty); ty += 34;
    x.font = '800 34px ' + IMG_FONT; x.fillStyle = '#111111'; r.nameL.forEach(l => { x.fillText(l, TX, ty); ty += 42; }); ty += 12;
    x.font = '400 26px ' + IMG_FONT; x.fillStyle = '#333333';
