async function savePdf(doc, name) {
  const blob = doc.output('blob'); const fn = (String(name || 'ovningar').replace(/[^\wåäöÅÄÖ \-]+/g, '').trim().slice(0, 60) || 'ovningar') + '.pdf';
  const dl = await useCap('downloads');
  if (dl) { try { await dl.save({ filename: fn, data: blob }); toast('PDF:en är sparad'); return; } catch (e) { if (e && e.code === 'declined') return; } }
  try { const file = new File([blob], fn, { type: 'application/pdf' }); if (navigator.canShare && navigator.canShare({ files: [file] })) { await navigator.share({ files: [file], title: name }); return; } } catch (e) { if (e && e.name === 'AbortError') return; }
  const u = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = u; a.download = fn; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(u), 4000);
}
