/* SvFF Övningsbanken: bygg bankposter av raderna (id, titel, skede, fas, typ, spelformer, organisation, spelare, målvakter, mål, fokus) */
SOURCES.svb = { org: 'Svenska Fotbollförbundet – Övningsbanken', title: 'Övningsbanken (861 övningar)', url: 'https://ovningsbanken.svenskfotboll.se/fotboll/tranare/ovningsbanken/ovningar/' };
STYLES.svb = { label: 'SvFF Övningsbanken', short: 'SvFF Övningsbanken', text: '' };
const SVB_URL = id => 'https://ovningsbanken.svenskfotboll.se/fotboll/tranare/ovningsbanken/ovningar/ShowExercise/?exerciseId=' + id;
const SVB_SF = { a: 3, b: 5, c: 7, d: 9, e: 11 };
const SVB_AGE = { 3: 6, 5: 8, 7: 10, 9: 13, 11: 15 };
const SVB_STAGE = { 'Återerövring av bollen': 'Återerövring' };
const SVB_PTS = {
  'Speluppbyggnad': ['Spelbarhet – sök fri yta', 'Speldjup framåt och bakåt', 'Spelvändning när det är stängt'],
  'Kontring': ['Snabbt framåt efter bollvinst', 'Löp i djupled', 'Avsluta innan försvaret är på plats'],
  'Komma till avslut och göra mål': ['Våga avsluta', 'Rätt tillslag för läget', 'Följ upp returer'],
  'Återerövring': ['Pressa direkt efter bollförlust', 'Närmaste pressar, nästa täcker', 'Vinn tillbaka som lag'],
  'Förhindra speluppbyggnad': ['Styr motståndaren mot en kant', 'Press med täckning', 'Kompakt lag'],
  'Förhindra och rädda avslut': ['Försvarssida mellan boll och mål', 'Blockera skott', 'Målvaktens position'],
};
CATS.push(['fys', 'Fotbollsfys och förberedelse', 'Fotbollsfys från SvFF: förberedelseträning, koordination, styrka, rörlighet och explosiv träning.']);
(function () {
  SVB_ROWS.forEach(r => {
    const [sid, t, sk0, ph0, ty0, sfc, org, np, gk, goals, labs] = r;
    const sk = SVB_STAGE[sk0] || sk0; const sf = String(sfc || '').split('').map(c => SVB_SF[c]).filter(Boolean);
    const isFys = ty0 === 'Fysövning' || /Fotbollsfys|förberedelse/i.test(ph0) || !PHASES.att.stages.concat(PHASES.def.stages, PHASES.tra.stages).includes(sk);
    const phase = ph0 === 'Försvarsspel' ? 'Försvar' : ph0 === 'Anfallsspel' ? 'Anfall' : 'Förberedelse';
    const stage = isFys ? '' : sk;
    const isGame = ty0 === 'Spelövning';
    let cat, type;
    if (sk0 === 'Lek') { cat = 'lek'; type = 'Lek med boll'; }
    else if (isFys) { cat = 'fys'; type = /uppvärmning|förberedelse/i.test(ph0) ? 'Skadeförebyggande uppvärmning' : 'Fys och koordination'; }
    else if (isGame) { type = 'Smålagsspel'; cat = stage === 'Speluppbyggnad' ? 'poss' : stage === 'Komma till avslut och göra mål' ? 'fin' : stage === 'Kontring' ? 'spel' : stage === 'Förhindra och rädda avslut' ? 'def' : 'press'; }
    else { cat = stage === 'Speluppbyggnad' ? 'pass' : stage === 'Komma till avslut och göra mål' || stage === 'Kontring' ? 'fin' : stage === 'Förhindra och rädda avslut' ? 'def' : 'duel';
      type = cat === 'pass' ? 'Passningsövning' : cat === 'fin' ? 'Avslutsövning' : 'Duell (1 mot 1, 2 mot 2)'; }
    const minSf = sf.length ? Math.min(...sf) : 9; const ages = (SVB_AGE[minSf] || 10) + '+';
    const tot = np + gk; const min = tot ? Math.max(1, tot - 2) : 4; const max = tot ? tot + 6 : 24;
    const pts = labs ? labs.split('|') : (SVB_PTS[stage] || ['Hög aktivitet', 'Kvalitet före antal', 'Följ SvFF:s anvisningar']);
    const id = 'svb' + sid;
    BANK.push({ id, name: t, style: 'svb', src: 'svb', cat, phase, stage, type, ages, level: minSf >= 9 ? 'B' : 'C', min, max, sfx: sf, url: SVB_URL(sid),
      orig: org || 'Se organisationen hos SvFF.', org: 'Hela upplägget, anvisningar och SvFF:s bild finns i Övningsbanken – tryck på "Öppna hos SvFF".',
      rules: 'Följ anvisningarna i SvFF:s Övningsbank.' + (labs ? ' Fokus: ' + labs.split('|').join(', ') + '.' : ''), points: pts });
    const half = Math.max(2, Math.min(8, Math.round((np || 8) / 2)));
    try {
      /* v29: välj mall efter vad organisationen faktiskt beskriver, inte bara övningstypen */
      const all = t + ' ' + (org || ''); const cnt = ssgCount(all);
      const gkIn = /målvakt/i.test(all) && !/utan målvakt|ingen målvakt/i.test(all);
      const gKind = /små mål|småmål|minimål|konmål|små konmål/i.test(org || '') ? 'small' : /2 mål|två mål|mål i varje|stora mål|mål på varje/i.test(org || '') ? 'big' : /\bmål\b/i.test(org || '') ? 'one' : (goals || 'none');
      const ballEach = /varsin boll|egen boll|alla (har |med )(en )?boll|en boll var/i.test(all);
      const teamGame = (cnt && cnt.a + cnt.b >= 4) || /\d\s*lag om|två lag|tre lag/i.test(all);
      const capsG = [stage || sk || t, pts[0] || '', pts[1] || '', pts[2] || '', gKind === 'none' ? 'Poäng' : 'Mål'];
      if (/^målvakt/i.test(t)) TPL.shoot(id, { caps: [t.replace(/^Målvakt\s*[A-C]?\s*-\s*/i, '') || 'Målvaktsträning', pts[0] || 'Grundposition', pts[1] || 'Rädda', 'Nästa'] });
      else if (teamGame && !/stafett/i.test(all)) TPL.ssg(id, { na: cnt ? cnt.a : half, nb: cnt ? cnt.b : Math.max(2, Math.min(8, (np || 8) - half)), jok: cnt && cnt.j ? cnt.j : 0, gk: gkIn || gk > 0, goals: gKind === 'one' && gkIn ? 'big' : gKind, caps: capsG });
      else if (gkIn && /\bmål\b/i.test(org || '') && !ballEach) TPL.shoot(id, { caps: [stage || sk || t, pts[0] || 'Ta emot', pts[1] || 'Avslut', 'Nästa'] });
      else if (isFys || ballEach) TPL.lek(id, { n: Math.max(4, Math.min(10, np || 8)), chasers: 0, ball: ballEach ? 'all' : undefined, caps: [sk || t || 'Förberedelseträning', pts[0] || 'Följ instruktionen', pts[1] || 'Kvalitet i rörelsen', 'Vila och upprepa'] });
      else if (isGame) TPL.ssg(id, { na: half, nb: Math.max(2, Math.min(8, (np || 8) - half)), gk: gk > 0, goals: goals || 'big', caps: [stage, pts[0] || '', pts[1] || '', pts[2] || '', 'Mål'] });
      else if (cat === 'fin') TPL.shoot(id, { caps: [stage, pts[0] || 'Ta emot', pts[1] || 'Avslut', 'Nästa'] });
      else if (cat === 'pass') TPL.pass(id, { pts: [[30, 44], [50, 22], [70, 44]], seq: [0, 1, 2, 0], follow: true, caps: [stage, pts[0] || 'Passa', pts[1] || 'Ta emot', pts[2] || 'Följ passningen'] });
      else TPL.duel(id, { to: stage === 'Förhindra och rädda avslut' ? 'goal' : 'line', caps: [stage, pts[0] || '', pts[1] || '', 'Byt roller'] });
    } catch (e) { }
  });
})();

/* SvFF-övningar som vi läst i sin helhet (PDF från Övningsbanken): egna ord, rätt kategori och spelform 3 mot 3 */
const SVB_FAKTA = {"svb45157": {"stage": "Speluppbyggnad", "org": "Tre mot tre på en yta cirka 15 × 12 m med ett litet mål i varje hörn. Varje lag anfaller två mål och försvarar två.", "rules": "Spela 3 mot 3. Ta dig förbi motståndare med bollen – driv, vänd, utmana, finta eller dribbla. Tappar du bollen, vinn tillbaka den direkt och driv bort från motståndaren. Progression: byt spelriktning, eller färre spelare på planen med snabba byten där de vilande hejar.", "points": ["Passera med bollen", "Bryt och vinn tillbaka direkt", "Driv bort efter bollvinst"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb122292": {"stage": "Komma till avslut och göra mål", "org": "Två lag med målvakter, 8–16 spelare, yta cirka 55 × 40 m med två mål.", "rules": "Spela enligt spelformens regler med fokus på 1 mot 1. Utespelare: bli rättvänd, utmana med riktningsförändring och tempoväxling, pressa sidställd och bryt mellan motståndarens tillslag. Målvakter: styr försvararna så att bollhållaren pressas bort från mål, fånga eller stöt bort bollen.", "points": ["Bli rättvänd", "Utmana – ändra riktning och tempo", "Pressa sidställd och bryt"], "phase": "Anfall", "type": "Smålagsspel", "cat": "fin", "sv_kalla": "pdf"}, "svb48719": {"stage": "Speluppbyggnad", "org": "6–11 spelare på en yta cirka 15 × 10 m med konmål. Två matcher pågår samtidigt i ytan.", "rules": "Spela 1 mot 1 mot konmål – två matcher i samma yta. Byt spelare när bollen går ur spel. Progression: 2 mot 2 i samma yta där lagen försvarar två mål var.", "points": ["Anfall och försvar i matchsituation", "Driv genom konmålet", "Progression 2 mot 2"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb140353": {"stage": "Speluppbyggnad", "org": "Två lag där varje spelare har ett nummer. Yta cirka 15 × 8 m med konmål i båda ändar.", "rules": "Tränaren ropar ett eller flera nummer. De spelarna springer in och spelar tills det blir mål eller bollen går ur spel. Mål görs genom att driva genom ett konmål – båda lagen kan göra mål åt båda hållen. Byt nummer efter en stund.", "points": ["Titta upp – vilket mål är ledigt?", "Vänd spelet till fri yta", "Försvaret: ta bollen och driv till fri yta"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb140478": {"stage": "Speluppbyggnad", "org": "Två lag på en yta cirka 18 × 12 m med ett målområde i varje ände.", "rules": "Lagen kastar bollen till varandra med handbollskast och ska ta sig framåt. Bollen måste studsa i golvet före varje passning, och man får inte springa med bollen. Mål görs genom att kasta till en lagkamrat i målområdet. Försvararna får bara bryta passningar, inte slå bollen ur händerna.", "points": ["Rörelse och spelbarhet", "Fånga med båda händerna, kroppen bakom", "Bryt och ställ om snabbt"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb45133": {"stage": "Speluppbyggnad", "org": "Cirka 6 spelare, yta 15 × 12 m med två små mål.", "rules": "Spela 3 mot 3. Var halvminut ändras antalet spelare på planen: 3v3 – 3v2 – 3v1 – 3v2 – 3v3 – 2v3 – 1v3 – 2v3 – 3v3. Kör två varv och låt olika spelare vara på planen i underläget.", "points": ["Passera med bollen i överläge", "Bryt och vinn tillbaka i underläge", "Driv bort efter bollvinst"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb140451": {"stage": "Speluppbyggnad", "org": "Cirka 6 spelare, yta 15 × 12 m med konmål eller småmål.", "rules": "Spela 3 mot 3. Var halvminut ändras antalet: 3v3 – 3v2 – 3v1 – 3v2 – 3v3 – 2v3 – 1v3 – 2v3 – 3v3. Två varv. I överläge: använd hela planen i anfall och pressa tillsammans i försvar. I underläge: styr och fördröj i försvar, var kreativ i anfall.", "points": ["Överläge: använd planens storlek", "Underläge: styr och fördröj", "Underläge i anfall: utmana kreativt"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb140356": {"stage": "Speluppbyggnad", "org": "Två lag, cirka 6 spelare, yta cirka 15 × 8 m med många konmål.", "rules": "Först har alla varsin boll och driver genom så många konmål som möjligt. Sedan spelar lagen mot varandra och gör mål genom att driva igenom valfritt konmål.", "points": ["Driv, finta och ändra riktning", "Titta upp – fria ytor och tomma mål", "Bryt och ställ om snabbt"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}, "svb140354": {"stage": "Speluppbyggnad", "org": "Cirka 6 spelare, yta cirka 15 × 8 m med två konmål eller små mål på varje sida.", "rules": "Spela 3 mot 3. Laget med bollen försöker göra mål genom att driva, finta och passa förbi motspelarna. Laget utan boll ska vinna bollen och ställa om till anfall. Progression: byt spelriktning så att planen blir bredare och kortare.", "points": ["Titta upp – vilket mål är bäst?", "Vänd spelet", "Erövra bollen och ställ om"], "phase": "Anfall", "type": "Smålagsspel", "cat": "poss", "sv_kalla": "pdf"}};
BANK.forEach(b => { const f = SVB_FAKTA[b.id]; if (!f) return; Object.assign(b, f, { orig: f.org }); if (!b.sfx.includes(3)) b.sfx = [3, ...b.sfx]; });
/* Rätt spelform direkt från SvFF */
const __sfFitList19 = sfFitList;
sfFitList = function (b) { return b && b.sfx && b.sfx.length ? b.sfx.map(n => n + 'v' + n) : __sfFitList19(b); };
/* Förberedelse och fys i passbyggaren: bara uppvärmning */
const __blockFit19 = blockFit;
blockFit = function (b, kind) { if (b && catOf(b) === 'fys') return kind === 'warm' && b.type === 'Skadeförebyggande uppvärmning'; return __blockFit19(b, kind); };
/* Länk till SvFF i övningsvyn */
const __detHTML19 = detHTML;
detHTML = function (ex) {
  const h = __detHTML19(ex); const b = ex && ex.fromBank ? bankById(ex.basedOn) : null; if (!b || !b.url) return h;
  const box = '<section class="det-sec svb-link"><h3>Hela övningen hos SvFF</h3><p>Anvisningar, progression, frågeexempel och SvFF:s egen bild finns i Övningsbanken.</p><a class="btn primary" href="' + esc(b.url) + '" target="_blank" rel="noopener">Öppna hos SvFF ↗</a></section>';
  const i = h.indexOf('<section class="det-sec">'); return i >= 0 ? h.slice(0, i) + box + h.slice(i) : h + box;
};
/* Land/källa i rullgardinen */
LANDS.splice(1, 0, ['svff', 'SvFF Övningsbanken']); LAND_NAME.svff = 'SvFF Övningsbanken';
const __landOf19 = landOf;
landOf = function (b) { return b && b.style === 'svb' ? 'svff' : __landOf19(b); };

