/* ---------- v34: aldrig fler spelare än spelformen tillåter ---------- */
/* 7, 8, 9 och 11 mot lika många räknar med målvakten. Handritade animationer med en spelare för mycket per lag trimmas. */
function sidesOf(an) { const ids = Object.keys(an.labels); const g = ids.filter(k => k[0] === 'g'); return { a: ids.filter(k => k[0] === 'a'), b: ids.filter(k => k[0] === 'b'), g }; }
function trimAnim(an, team, k) {
  const S = sidesOf(an); const list = S[team].slice().sort((x, y) => Number(y.slice(1)) - Number(x.slice(1)));
  const holds = new Set(an.frames.map(f => f.b).filter(x => typeof x === 'string'));
  const drop = list.filter(x => !holds.has(x)).slice(0, k);
  drop.forEach(x => { delete an.labels[x]; an.frames.forEach(f => { if (f.p) delete f.p[x]; }); });
  return drop.length;
}
(function () {
  let fixed = 0;
  BANK.forEach(b => {
    const an = ANIMS[b.id]; if (!an) return;
    const t = ssgCount(b.name) || ssgCount(b.orig || ''); if (!t || !t.fmt) return;
    if (ssgCount((b.orig || '') + ' ' + (b.org || '') + ' ' + (b.rules || '')) && !ssgCount((b.orig || '') + ' ' + (b.org || '') + ' ' + (b.rules || '')).fmt) return;
    const S = sidesOf(an); const ga = S.g.length >= 1 ? 1 : 0, gb = S.g.length >= 2 ? 1 : 0;
    const ea = S.a.length + ga - t.a, eb = S.b.length + gb - t.b;
    if (ea > 0) fixed += trimAnim(an, 'a', ea); if (eb > 0) fixed += trimAnim(an, 'b', eb);
  });
  if (fixed) { Object.keys(AQ).forEach(k => delete AQ[k]); __animSig = null; }
})();
/* Kontrollen säger också till när det är fler spelare än spelformen tillåter */
const __animCheck34 = animCheck;
animCheck = function (b) {
  const q = __animCheck34.apply(this, arguments); if (!q || !b) return q;
  const an = ANIMS[b.id]; if (!an || q.__fmt) return q; q.__fmt = true;
  const setup = ((b.orig || '') + '. ' + (b.org || '') + '. ' + (b.rules || '')).split(/(?<=[.!?])\s+/).filter(x => !/variant|större|mindre|progression|nivå|svårare|lättare/i.test(x)).join(' ');
  const t = ssgCount(setup) || ssgCount(b.name); const S = sidesOf(an);
  const pa = S.a.length + (S.g.length >= 1 ? 1 : 0), pb = S.b.length + (S.g.length >= 2 ? 1 : 0);
  if ((t && t.fmt && (pa > t.a || pb > t.b)) || (/Matchlikt|Smålagsspel/.test(b.type || '') && (pa > 11 || pb > 11))) { q.issues.push('För många spelare: animationen har ' + pa + ' mot ' + pb + ' inklusive målvakter.'); q.level = 'mismatch'; }
  return q;
};

