async function startWorkspace() {
try {
  if (coachSync) {
    await loadCoachPlans();
    const notice = document.createElement('p');
    notice.id = 'coach-sync';
    notice.className = 'of-coach-sync-status';
    notice.setAttribute('role','status');
    document.querySelector('#app').before(notice);
    coachSyncNotice();
  }
  restore();
  if (SIGNED_IN_TEAM && ST.team !== SIGNED_IN_TEAM) {
    const authenticatedTeam = CLUB_TEAMS.find(t => t.id === SIGNED_IN_TEAM);
    if (!authenticatedTeam) throw new Error('Det inloggade laget saknas i lagkatalogen.');
    applyTeam(authenticatedTeam);
    ST.lpAge = Math.max(8, Math.min(17, authenticatedTeam.u));
    ST.bankJ = { t: authenticatedTeam.id, sf: '' };
  }
  if (SIGNED_IN_TEAM && ST.bankJ?.t && !workspaceVisibleTeams().some(t => t.id === ST.bankJ.t)) ST.bankJ = { t: SIGNED_IN_TEAM, sf: '' };
  if (!ST.workspaceStarted) {
    ST.workspaceStarted = true;
    ST.view = 'today';
    persist();
  }
  render();
  if (!PERSONAL_COACH && !IS_OPEN) initDb().catch(error => console.error('Kunde inte starta lagringen', error));
} catch (error) {
  console.error('Övningsfabriken kunde inte starta', error);
  const app = $('#app');
  app.innerHTML = '<h1>Övningsfabriken</h1><p role="alert">Sidan eller lagets planering kunde inte laddas. Ladda om och försök igen.</p>';
}


}
startWorkspace();
